window.LUAU_FILES={"client/Controllers/KnockbackReceiver.client.lua":"local replicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal knockback = require(replicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"Modules\"):WaitForChild(\"Knockback\"))\n\nknockback.remote.OnClientEvent:Connect(function(model, root, ...)\n\tif model and root and root:IsDescendantOf(workspace) then\n\t\tknockback.apply(model, root, ...)\n\tend\nend)","client/Skills/ElThor.client.lua":"local players = game:GetService(\"Players\")\nlocal replicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal tweenService = game:GetService(\"TweenService\")\nlocal userInputService = game:GetService(\"UserInputService\")\n\nlocal modules = replicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"Modules\")\nlocal characters = require(modules:WaitForChild(\"Characters\"))\nlocal elThorFx = require(modules:WaitForChild(\"ElThorFX\"))\nlocal skillFx = require(modules:WaitForChild(\"SkillFX\"))\n\nlocal vfx = replicatedStorage:WaitForChild(\"Assets\"):WaitForChild(\"VFX\")\nlocal cloudVfx = vfx:WaitForChild(\"Cloud\")\nlocal floorVfx = vfx:WaitForChild(\"Floor\")\nlocal handVfx = vfx:WaitForChild(\"HandVFX\")\nlocal beamVfx = vfx:WaitForChild(\"Beam\")\n\nlocal impactEvent = replicatedStorage:WaitForChild(\"ElThorImpact\")\nlocal player = players.LocalPlayer\n\nlocal maxRange = 800\nlocal cloudHeight = 200\nlocal dropTime = 0.05\nlocal growTime = 0.6\nlocal returnTime = 0.3\n\nlocal casting = false\n\nlocal function setEmitters(att, enabled)\n\tif not att then return end\n\tfor _, e in ipairs(att:GetChildren()) do\n\t\tif e:IsA(\"ParticleEmitter\") then\n\t\t\te.Enabled = enabled\n\t\tend\n\tend\nend\n\nlocal function beamParts(beam)\n\tlocal parts = {}\n\tfor _, p in ipairs(beam:GetChildren()) do\n\t\tif p:IsA(\"BasePart\") then\n\t\t\ttable.insert(parts, p)\n\t\tend\n\tend\n\treturn parts\nend\n\nlocal function width(part, w)\n\tif part.Name == \"Outside\" then\n\t\treturn w + 5\n\tend\n\treturn w\nend\n\nlocal function attachHand(char)\n\tlocal hand = char:FindFirstChild(\"LeftHand\")\n\tlocal offset = CFrame.new()\n\tif not hand then\n\t\thand = char:FindFirstChild(\"Left Arm\")\n\t\tif not hand then return end\n\t\toffset = CFrame.new(0, -hand.Size.Y / 2, 0)\n\tend\n\n\tlocal fx = handVfx:Clone()\n\tfx.Anchored = false\n\tfx.CanCollide = false\n\tfx.CanQuery = false\n\tfx.Massless = true\n\tfx.CFrame = hand.CFrame * offset\n\tfx.Parent = workspace\n\n\tlocal weld = Instance.new(\"WeldConstraint\")\n\tweld.Part0 = fx\n\tweld.Part1 = hand\n\tweld.Parent = fx\n\n\tsetEmitters(fx:FindFirstChildOfClass(\"Attachment\"), true)\n\treturn fx\nend\n\nlocal function useElThor()\n\tif casting then return end\n\tlocal char = player.Character\n\tlocal hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n\tif not hrp then return end\n\tcasting = true\n\n\tlocal handFx = attachHand(char)\n\tlocal stopCharge = elThorFx.charge(handFx)\n\ttask.wait(0.15)\n\n\tlocal mouse = userInputService:GetMouseLocation()\n\tlocal ray = workspace.CurrentCamera:ViewportPointToRay(mouse.X, mouse.Y)\n\tlocal hit = workspace:Raycast(ray.Origin, ray.Direction * maxRange, characters.excludeParams())\n\tlocal tooFar = hit and (hit.Position - hrp.Position).Magnitude > maxRange\n\tif not hit or tooFar or not characters.canSee(char, hit.Position) then\n\t\tif handFx then handFx:Destroy() end\n\t\tstopCharge()\n\t\tcasting = false\n\t\treturn\n\tend\n\n\tlocal cloud = cloudVfx:Clone()\n\tcloud.Anchored = true\n\tcloud.CanCollide = false\n\tcloud.CFrame = CFrame.new(hit.Position + Vector3.new(0, cloudHeight, 0))\n\tlocal cloudTransparency = cloud.Transparency\n\tcloud.Transparency = 1\n\tcloud.Parent = workspace\n\ttweenService:Create(cloud, TweenInfo.new(0.05, Enum.EasingStyle.Quad), {Transparency = cloudTransparency}):Play()\n\n\tlocal floor = floorVfx:Clone()\n\tfloor.Anchored = true\n\tfloor.CanCollide = false\n\tfloor.Transparency = 1\n\tfloor.CFrame = cloud.CFrame\n\tfloor.Parent = workspace\n\tlocal floorAtt = floor:FindFirstChildOfClass(\"Attachment\")\n\tsetEmitters(floorAtt, false)\n\n\telThorFx.storm()\n\n\tlocal beam = beamVfx:Clone()\n\tfor _, p in ipairs(beamParts(beam)) do\n\t\tlocal w = width(p, 30)\n\t\tp.Anchored = true\n\t\tp.CanCollide = false\n\t\tp.CFrame = CFrame.new(cloud.Position) * p.CFrame.Rotation\n\t\tp.Size = Vector3.new(0.05, w, w)\n\tend\n\tbeam.Parent = workspace\n\n\tif handFx then\n\t\tsetEmitters(handFx:FindFirstChildOfClass(\"Attachment\"), false)\n\tend\n\tstopCharge()\n\n\tlocal drop = tweenService:Create(floor, TweenInfo.new(dropTime, Enum.EasingStyle.Linear), {CFrame = CFrame.new(hit.Position)})\n\tdrop:Play()\n\n\tlocal length = cloud.Position.Y - hit.Position.Y\n\tlocal middle = cloud.Position - Vector3.new(0, length / 2, 0)\n\tfor _, p in ipairs(beamParts(beam)) do\n\t\ttweenService:Create(p, TweenInfo.new(dropTime, Enum.EasingStyle.Linear), {\n\t\t\tSize = Vector3.new(length, p.Size.Y, p.Size.Z),\n\t\t\tCFrame = CFrame.new(middle) * p.CFrame.Rotation,\n\t\t}):Play()\n\tend\n\tdrop.Completed:Wait()\n\n\tif floorAtt then\n\t\tfor _, e in ipairs(floorAtt:GetChildren()) do\n\t\t\tif e:IsA(\"ParticleEmitter\") then\n\t\t\t\te:Emit(e:GetAttribute(\"EmitCount\") or 50)\n\t\t\tend\n\t\tend\n\tend\n\timpactEvent:FireServer(hit.Position)\n\telThorFx.strike(hit, cloud.Position, char)\n\n\tlocal started = os.clock()\n\tfor _, p in ipairs(beamParts(beam)) do\n\t\tlocal t = p.Transparency\n\t\tlocal w = width(p, 100)\n\t\ttweenService:Create(p, TweenInfo.new(0.2, Enum.EasingStyle.Quad), {Transparency = 0.9}):Play()\n\t\ttask.delay(0.2, function()\n\t\t\ttweenService:Create(p, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Transparency = t}):Play()\n\t\tend)\n\t\ttweenService:Create(p, TweenInfo.new(growTime, Enum.EasingStyle.Quad), {Size = Vector3.new(p.Size.X, w, w)}):Play()\n\tend\n\n\tlocal rings = {}\n\tfor i = 1, 2 do\n\t\tlocal size = 3 - i\n\t\ttable.insert(rings, skillFx.rockRing(hit.Position, 40 + (i - 1) * 15, 7 * size, 3.5 * size, 1.5 * size, 100))\n\t\ttask.wait(0.05)\n\tend\n\n\tlocal left = growTime - (os.clock() - started)\n\tif left > 0 then\n\t\ttask.wait(left)\n\tend\n\n\ttweenService:Create(floor, TweenInfo.new(returnTime, Enum.EasingStyle.Quad), {CFrame = cloud.CFrame}):Play()\n\ttweenService:Create(cloud, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Transparency = 1}):Play()\n\tfor _, p in ipairs(beamParts(beam)) do\n\t\ttweenService:Create(p, TweenInfo.new(returnTime, Enum.EasingStyle.Quad), {\n\t\t\tSize = Vector3.new(0.05, p.Size.Y, p.Size.Z),\n\t\t\tCFrame = CFrame.new(cloud.Position) * p.CFrame.Rotation,\n\t\t}):Play()\n\tend\n\ttask.delay(returnTime, function()\n\t\tbeam:Destroy()\n\tend)\n\n\ttask.wait(1.5)\n\tfor _, sink in ipairs(rings) do\n\t\tsink(0.4)\n\t\ttask.wait(0.05)\n\tend\n\ttask.wait(0.4)\n\n\tif handFx then handFx:Destroy() end\n\tcloud:Destroy()\n\tfloor:Destroy()\n\tcasting = false\nend\n\nuserInputService.InputBegan:Connect(function(input, gameProcessed)\n\tif not gameProcessed and input.KeyCode == Enum.KeyCode.Q then\n\t\ttask.spawn(useElThor)\n\tend\nend)","client/Skills/Plunge.client.lua":"local players = game:GetService(\"Players\")\nlocal replicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal runService = game:GetService(\"RunService\")\nlocal userInputService = game:GetService(\"UserInputService\")\n\nlocal plungeFx = require(replicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"Modules\"):WaitForChild(\"PlungeFX\"))\nlocal remote = replicatedStorage:WaitForChild(\"PlungeCast\")\n\nlocal player = players.LocalPlayer\n\nlocal leapDistance = 30\nlocal leapHeight = 3.5\nlocal leapTime = 0.4\n\nlocal casting = false\n\nlocal function forward(hrp)\n\tlocal look = hrp.CFrame.LookVector * Vector3.new(1, 0, 1)\n\tif look.Magnitude < 0.001 then\n\t\treturn Vector3.new(0, 0, -1)\n\tend\n\treturn look.Unit\nend\n\nlocal function velocity(hrp, name, maxForce)\n\tlocal att = Instance.new(\"Attachment\")\n\tatt.Name = name\n\tatt.Parent = hrp\n\n\tlocal lv = Instance.new(\"LinearVelocity\")\n\tlv.Name = name\n\tlv.Attachment0 = att\n\tlv.RelativeTo = Enum.ActuatorRelativeTo.World\n\tlv.ForceLimitMode = Enum.ForceLimitMode.PerAxis\n\tlv.MaxAxesForce = maxForce\n\tlv.Parent = hrp\n\n\treturn lv, function()\n\t\tlv:Destroy()\n\t\tatt:Destroy()\n\tend\nend\n\nlocal function leap(character, hrp)\n\tlocal dir = forward(hrp)\n\tlocal params = RaycastParams.new()\n\tparams.FilterDescendantsInstances = {character}\n\n\tlocal dist = leapDistance\n\tlocal wall = workspace:Raycast(hrp.Position, dir * dist, params)\n\tif wall then\n\t\tdist = math.max(0, (wall.Position - hrp.Position).Magnitude - 2)\n\tend\n\n\tlocal rise = 0\n\tlocal here = workspace:Raycast(hrp.Position, Vector3.new(0, -10, 0), params)\n\tlocal there = workspace:Raycast(hrp.Position + dir * dist + Vector3.new(0, 6, 0), Vector3.new(0, -24, 0), params)\n\tif here and there then\n\t\trise = there.Position.Y - here.Position.Y\n\tend\n\n\tlocal lv, remove = velocity(hrp, \"PlungeLeap\", Vector3.one * math.huge)\n\tlocal start = os.clock()\n\tlocal conn\n\tlocal function update()\n\t\tlocal t = (os.clock() - start) / leapTime\n\t\tif t >= 1 or not hrp.Parent then\n\t\t\tconn:Disconnect()\n\t\t\tremove()\n\t\t\treturn\n\t\tend\n\t\tlocal horizontal = dir * (2 * dist * (1 - t) / leapTime)\n\t\tlocal vertical = (4 * leapHeight * (1 - 2 * t) + rise) / leapTime\n\t\tlv.VectorVelocity = horizontal + Vector3.new(0, vertical, 0)\n\tend\n\tconn = runService.Stepped:Connect(update)\n\tupdate()\nend\n\nlocal function onGround(hum)\n\treturn hum.FloorMaterial ~= Enum.Material.Air\nend\n\nlocal function waitForGround(hum, hrp, timeout, dive)\n\tif onGround(hum) then return true end\n\n\tlocal remove\n\tif dive then\n\t\tlocal lv\n\t\tlv, remove = velocity(hrp, \"PlungeDive\", Vector3.new(0, math.huge, 0))\n\t\tlv.VectorVelocity = Vector3.new(0, -dive, 0)\n\tend\n\n\tlocal start = os.clock()\n\trepeat\n\t\trunService.Heartbeat:Wait()\n\tuntil onGround(hum) or not hrp.Parent or os.clock() - start > timeout\n\n\tif remove then remove() end\n\treturn hrp.Parent ~= nil and onGround(hum)\nend\n\nlocal function plunge()\n\tlocal char = player.Character\n\tlocal hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n\tlocal hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n\tif casting or not hum or not hrp then\n\t\treturn\n\tend\n\tcasting = true\n\n\tif not waitForGround(hum, hrp, 1.5) then\n\t\tcasting = false\n\t\treturn\n\tend\n\n\tlocal walkSpeed, jumpPower, jumpHeight = hum.WalkSpeed, hum.JumpPower, hum.JumpHeight\n\thum.JumpPower = 0\n\thum.JumpHeight = 0\n\n\tlocal dash, stopDash = velocity(hrp, \"PlungeDash\", Vector3.new(math.huge, 0, math.huge))\n\tdash.VectorVelocity = forward(hrp) * 35\n\ttask.delay(0.1, stopDash)\n\n\ttask.wait(0.15)\n\tif waitForGround(hum, hrp, 1.5) then\n\t\tremote:FireServer(\"groundspear\")\n\t\thum.WalkSpeed = 0\n\tend\n\n\ttask.wait(0.5)\n\thum.WalkSpeed = walkSpeed\n\tleap(char, hrp)\n\tplungeFx.leap(char)\n\n\ttask.wait(0.45)\n\tif waitForGround(hum, hrp, 1.5, 120) then\n\t\tremote:FireServer(\"slam\", hrp.Position)\n\t\tplungeFx.slam(char, forward(hrp))\n\tend\n\thum.WalkSpeed = 2\n\n\ttask.wait(0.5)\n\thum.WalkSpeed = walkSpeed\n\n\ttask.wait(1.5)\n\thum.JumpPower = jumpPower\n\thum.JumpHeight = jumpHeight\n\tcasting = false\nend\n\nuserInputService.InputBegan:Connect(function(input, gp)\n\tif gp then return end\n\tif input.KeyCode == Enum.KeyCode.F then\n\t\ttask.spawn(plunge)\n\tend\nend)","server/Skills/ElThor.server.lua":"local players = game:GetService(\"Players\")\nlocal replicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal characters = require(replicatedStorage.Shared.Modules.Characters)\nlocal knockback = require(replicatedStorage.Shared.Modules.Knockback)\n\nlocal remote = Instance.new(\"RemoteEvent\")\nremote.Name = \"ElThorImpact\"\nremote.Parent = replicatedStorage\n\nlocal cooldowns = {}\n\nlocal function ragdoll(model, hum)\n\thum.AutoRotate = false\n\thum.PlatformStand = true\n\thum.RequiresNeck = false\n\tpcall(function()\n\t\thum:ChangeState(Enum.HumanoidStateType.Physics)\n\tend)\n\n\tfor _, joint in ipairs(model:GetDescendants()) do\n\t\tif joint:IsA(\"Motor6D\") and joint.Name ~= \"RootJoint\" and joint.Name ~= \"Root\" and joint.Part0 and joint.Part1 then\n\t\t\tlocal a0 = Instance.new(\"Attachment\")\n\t\t\ta0.CFrame = joint.C0\n\t\t\ta0.Parent = joint.Part0\n\t\t\tlocal a1 = Instance.new(\"Attachment\")\n\t\t\ta1.CFrame = joint.C1\n\t\t\ta1.Parent = joint.Part1\n\n\t\t\tlocal socket = Instance.new(\"BallSocketConstraint\")\n\t\t\tsocket.Attachment0 = a0\n\t\t\tsocket.Attachment1 = a1\n\t\t\tsocket.LimitsEnabled = true\n\t\t\tsocket.UpperAngle = 60\n\t\t\tsocket.TwistLimitsEnabled = true\n\t\t\tsocket.TwistLowerAngle = -45\n\t\t\tsocket.TwistUpperAngle = 45\n\t\t\tsocket.Parent = joint.Part0\n\n\t\t\tjoint:Destroy()\n\t\tend\n\tend\nend\n\nremote.OnServerEvent:Connect(function(player, pos)\n\tif typeof(pos) ~= \"Vector3\" then return end\n\n\tlocal char = player.Character\n\tlocal hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n\tlocal hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n\tif not hum or hum.Health <= 0 or not hrp then return end\n\n\tlocal dist = (pos - hrp.Position).Magnitude\n\tif dist ~= dist or dist > 800 then return end\n\tif not characters.canSee(char, pos) then return end\n\n\tlocal now = os.clock()\n\tif cooldowns[player] and now - cooldowns[player] < 2.5 then return end\n\tcooldowns[player] = now\n\n\tlocal hit = {}\n\tfor _, part in ipairs(workspace:GetPartBoundsInRadius(pos, 30)) do\n\t\tlocal model = part:FindFirstAncestorOfClass(\"Model\")\n\t\tlocal victim = model and model ~= char and model:FindFirstChildOfClass(\"Humanoid\")\n\t\tif victim and not hit[victim] then\n\t\t\thit[victim] = true\n\t\t\tvictim:TakeDamage(50)\n\n\t\t\tif not players:GetPlayerFromCharacter(model) then\n\t\t\t\tragdoll(model, victim)\n\t\t\t\tlocal root = model:FindFirstChild(\"HumanoidRootPart\") or model:FindFirstChild(\"Torso\")\n\t\t\t\tif root then\n\t\t\t\t\tlocal a = math.random() * math.pi * 2\n\t\t\t\t\tknockback.send(model, root, Vector3.new(math.cos(a), 0, math.sin(a)), 9, 3.5, 0.55, player)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend)\n\nplayers.PlayerRemoving:Connect(function(player)\n\tcooldowns[player] = nil\nend)","server/Skills/Plunge.server.lua":"local players = game:GetService(\"Players\")\nlocal replicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal tweenService = game:GetService(\"TweenService\")\nlocal debris = game:GetService(\"Debris\")\n\nlocal modules = replicatedStorage.Shared.Modules\nlocal characters = require(modules.Characters)\nlocal knockback = require(modules.Knockback)\nlocal plungeFx = require(modules.PlungeFX)\n\nlocal mainTemplate = replicatedStorage.Assets.VFX.Main\nlocal slamTemplate = replicatedStorage.Assets.VFX.Slam\n\nlocal damage = 20\nlocal boxSize = Vector3.new(14, 8, 14)\nlocal cooldown = 2.8\n\nlocal slamSteps = {\n\t{from = Vector3.one * 0.6, to = Vector3.one * 1.4, time = 0.096, style = Enum.EasingStyle.Back, spin = 0},\n\t{from = Vector3.one * 0.85, to = Vector3.one * 0.8, time = 0.224, style = Enum.EasingStyle.Quart, spin = 0},\n}\nlocal blackWindSteps = {\n\t{from = Vector3.new(0.1, 1, 0.1), to = Vector3.new(1.836, 1, 1.836), time = 0.096, style = Enum.EasingStyle.Back, spin = 180},\n\t{from = Vector3.new(0.1, 1, 0.1), to = Vector3.new(1.836, 1, 1.836), time = 0.232, style = Enum.EasingStyle.Quart, spin = 180},\n}\nlocal windStep = {from = Vector3.new(7.2, 1, 7.2), to = Vector3.new(7.2, 1, 7.2), time = 0.328, style = Enum.EasingStyle.Quart, spin = 180}\n\nlocal remote = Instance.new(\"RemoteEvent\")\nremote.Name = \"PlungeCast\"\nremote.Parent = replicatedStorage\n\nlocal lastUse = {}\n\nlocal function onCooldown(player, phase)\n\tlocal now = os.clock()\n\tlastUse[player] = lastUse[player] or {}\n\tlocal last = lastUse[player][phase]\n\tif last and now - last < cooldown then\n\t\treturn true\n\tend\n\tlastUse[player][phase] = now\n\treturn false\nend\n\nlocal function emitCount(e)\n\tlocal n = e:GetAttribute(\"EmitCount\")\n\treturn type(n) == \"number\" and n or 30\nend\n\nlocal function burstMain(root, mult)\n\tlocal main = mainTemplate:Clone()\n\tmain.Parent = root\n\n\tlocal life = 3\n\tfor _, e in ipairs(main:GetDescendants()) do\n\t\tif e:IsA(\"ParticleEmitter\") then\n\t\t\te:Emit(emitCount(e) * mult)\n\t\t\tlife = math.max(life, e.Lifetime.Max)\n\t\tend\n\tend\n\tdebris:AddItem(main, life + 0.5)\nend\n\nlocal function moveTo(obj, pos)\n\tif obj:IsA(\"Model\") then\n\t\tobj:PivotTo(obj:GetPivot().Rotation + pos)\n\telse\n\t\tobj.CFrame = obj.CFrame.Rotation + pos\n\tend\nend\n\nlocal function findMesh(obj, name)\n\tlocal named = obj:FindFirstChild(name, true)\n\tif named and named:IsA(\"BasePart\") then\n\t\treturn named\n\tend\n\tif obj:IsA(\"MeshPart\") then\n\t\treturn obj\n\tend\n\tif obj:IsA(\"Model\") then\n\t\tfor _, d in ipairs(obj:GetDescendants()) do\n\t\t\tif d:IsA(\"MeshPart\") and d ~= obj.PrimaryPart then\n\t\t\t\treturn d\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal function prep(mesh)\n\tmesh.Anchored = true\n\tmesh.CanCollide = false\n\tmesh.CastShadow = false\nend\n\nlocal function play(mesh, b)\n\tif not mesh.Parent then return end\n\tlocal size = mesh.Size\n\tmesh.Size = size * b.from\n\tmesh.Transparency = 0.85\n\ttweenService:Create(mesh, TweenInfo.new(b.time, b.style), {\n\t\tSize = size * b.to,\n\t\tTransparency = 1,\n\t\tCFrame = mesh.CFrame * CFrame.Angles(0, math.rad(b.spin), 0),\n\t}):Play()\nend\n\nlocal function playPair(obj, steps)\n\tlocal first = findMesh(obj, \"Start\")\n\tif not first then\n\t\treturn 0\n\tend\n\tlocal second = findMesh(obj, \"End\") or first\n\n\tprep(first)\n\tif second ~= first then\n\t\tprep(second)\n\t\tsecond.Transparency = 1\n\tend\n\n\tplay(first, steps[1])\n\ttask.delay(steps[1].time * 0.6, play, second, steps[2])\n\treturn steps[1].time + steps[2].time\nend\n\nlocal function playWind(obj)\n\tlocal mesh = findMesh(obj, \"End\")\n\tif not mesh then\n\t\treturn 0\n\tend\n\tprep(mesh)\n\n\tif obj:IsA(\"Model\") then\n\t\tfor _, d in ipairs(obj:GetDescendants()) do\n\t\t\tif d:IsA(\"BasePart\") and d ~= mesh and d ~= obj.PrimaryPart then\n\t\t\t\td.Transparency = 1\n\t\t\tend\n\t\tend\n\tend\n\n\tplay(mesh, windStep)\n\treturn windStep.time\nend\n\nlocal function playSlamVFX(pos)\n\tlocal vfx = slamTemplate:Clone()\n\tvfx.Parent = workspace\n\n\tlocal duration = 0\n\tlocal slamMesh = vfx:FindFirstChild(\"Slam\")\n\tif slamMesh then\n\t\tmoveTo(slamMesh, pos + Vector3.new(0, 2.7, 0))\n\t\tduration = playPair(slamMesh, slamSteps)\n\tend\n\tlocal wind = vfx:FindFirstChild(\"Wind\")\n\tif wind then\n\t\tmoveTo(wind, pos + Vector3.new(0, 0.2, 0))\n\t\tduration = math.max(duration, playWind(wind))\n\tend\n\tlocal blackWind = vfx:FindFirstChild(\"BlackWind\")\n\tif blackWind then\n\t\tmoveTo(blackWind, pos + Vector3.new(0, 2.5, 0))\n\t\tduration = math.max(duration, playPair(blackWind, blackWindSteps))\n\tend\n\n\tfor _, e in ipairs(vfx:GetDescendants()) do\n\t\tif e:IsA(\"ParticleEmitter\") then\n\t\t\te:Emit(emitCount(e))\n\t\t\tduration = math.max(duration, e.Lifetime.Max)\n\t\tend\n\tend\n\tdebris:AddItem(vfx, duration + 0.5)\nend\n\nlocal function slam(character, pos, dir)\n\tlocal groundY = pos.Y\n\tlocal ground = workspace:Raycast(pos, Vector3.new(0, -20, 0), characters.excludeParams())\n\tif ground then\n\t\tgroundY = ground.Position.Y\n\tend\n\n\tlocal ahead = pos + dir * boxSize.Z / 2\n\tlocal floor = Vector3.new(ahead.X, groundY, ahead.Z)\n\tlocal center = floor + Vector3.new(0, boxSize.Y / 2, 0)\n\n\tplaySlamVFX(floor - dir * 3 - Vector3.new(0, 0.5, 0))\n\n\tlocal caster = players:GetPlayerFromCharacter(character)\n\tlocal hit = {}\n\tfor _, part in ipairs(workspace:GetPartBoundsInBox(CFrame.lookAt(center, center + dir), boxSize)) do\n\t\tlocal model = part:FindFirstAncestorOfClass(\"Model\")\n\t\tlocal hum = model and model ~= character and model:FindFirstChildOfClass(\"Humanoid\")\n\t\tlocal hrp = hum and model:FindFirstChild(\"HumanoidRootPart\")\n\t\tif hrp and not hit[model] then\n\t\t\thit[model] = true\n\t\t\thum:TakeDamage(damage)\n\t\t\tplungeFx.hit(model)\n\n\t\t\tlocal away = (hrp.Position - center) * Vector3.new(1, 0, 1)\n\t\t\tif away.Magnitude < 0.001 then\n\t\t\t\taway = dir\n\t\t\tend\n\t\t\tknockback.send(model, hrp, away.Unit, 9, 3.5, 0.4, caster)\n\t\tend\n\tend\n\n\tplungeFx.slamWorld(floor - dir * 1.5)\nend\n\nremote.OnServerEvent:Connect(function(player, phase, pos)\n\tif phase ~= \"groundspear\" and phase ~= \"slam\" then return end\n\n\tlocal char = player.Character\n\tlocal hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n\tlocal root = char and char:FindFirstChild(\"HumanoidRootPart\")\n\tif not hum or hum.Health <= 0 or not root then return end\n\n\tif phase == \"groundspear\" then\n\t\tif onCooldown(player, phase) then return end\n\t\tburstMain(root, 1)\n\t\treturn\n\tend\n\n\tif typeof(pos) ~= \"Vector3\" then return end\n\tlocal offset = (pos - root.Position).Magnitude\n\tlocal maxOffset = 10 + root.AssemblyLinearVelocity.Magnitude * 0.35\n\tif offset ~= offset or offset > maxOffset then return end\n\n\tlocal dir = root.CFrame.LookVector * Vector3.new(1, 0, 1)\n\tif dir.Magnitude < 0.001 then return end\n\tif onCooldown(player, phase) then return end\n\n\tburstMain(root, 2)\n\tslam(char, pos, dir.Unit)\nend)\n\nplayers.PlayerRemoving:Connect(function(player)\n\tlastUse[player] = nil\nend)","shared/Modules/Characters.lua":"local players = game:GetService(\"Players\")\n\nlocal characters = {}\n\nfunction characters.all()\n\tlocal list = {}\n\tfor _, player in ipairs(players:GetPlayers()) do\n\t\tif player.Character then\n\t\t\ttable.insert(list, player.Character)\n\t\tend\n\tend\n\tfor _, model in ipairs(workspace:GetChildren()) do\n\t\tif model:IsA(\"Model\") and model:FindFirstChildOfClass(\"Humanoid\") and not table.find(list, model) then\n\t\t\ttable.insert(list, model)\n\t\tend\n\tend\n\treturn list\nend\n\nfunction characters.excludeParams()\n\tlocal params = RaycastParams.new()\n\tparams.FilterType = Enum.RaycastFilterType.Exclude\n\tparams.FilterDescendantsInstances = characters.all()\n\treturn params\nend\n\nfunction characters.canSee(character, pos)\n\tlocal head = character:FindFirstChild(\"Head\")\n\tif not head then\n\t\treturn false\n\tend\n\tlocal hit = workspace:Raycast(head.Position, pos - head.Position, characters.excludeParams())\n\treturn not hit or (hit.Position - pos).Magnitude < 5\nend\n\nreturn characters","shared/Modules/ElThorFX.lua":"local skillFx = require(script.Parent:WaitForChild(\"SkillFX\"))\n\nlocal blue = Color3.fromRGB(105, 189, 255)\nlocal lightBlue = Color3.fromRGB(215, 240, 255)\nlocal crackTexture = \"rbxassetid://106039714929540\"\n\nlocal elThorFx = {}\n\nlocal function rand(min, max)\n\treturn min + math.random() * (max - min)\nend\n\nfunction elThorFx.charge(part)\n\tif part then\n\t\treturn skillFx.glow(part, blue, 4, 12)\n\tend\n\treturn function() end\nend\n\nfunction elThorFx.storm()\n\tskillFx.tint({Brightness = -0.07, Contrast = 0.15, Saturation = -0.3, TintColor = Color3.fromRGB(205, 220, 255)}, 0.08, 0.8, 0.6)\nend\n\nfunction elThorFx.strike(hit, cloudPos, caster)\n\tlocal pos, normal = hit.Position, hit.Normal\n\tlocal groundColor = skillFx.surfaceColor(hit)\n\n\tlocal bolts = Instance.new(\"Model\")\n\tbolts.Name = \"ElThorBolts\"\n\tbolts.Parent = skillFx.folder()\n\tgame:GetService(\"Debris\"):AddItem(bolts, 1.5)\n\n\tlocal cloudBase = cloudPos - Vector3.new(0, 40, 0)\n\tfor i = 1, 5 do\n\t\tlocal angle = i / 5 * math.pi * 2 + rand(-0.4, 0.4)\n\t\tlocal ground = pos + Vector3.new(math.cos(angle), 0, math.sin(angle)) * rand(14, 46)\n\t\tskillFx.bolt(cloudBase + Vector3.new(rand(-45, 45), 0, rand(-45, 45)), ground, {\n\t\t\tcolor = i % 2 == 0 and blue or lightBlue,\n\t\t\tthickness = rand(0.9, 1.6),\n\t\t\tsegments = 12,\n\t\t\tjag = 14,\n\t\t\tlife = rand(0.18, 0.3),\n\t\t\tflickers = 2,\n\t\t\tbranches = 2,\n\t\t\tparent = bolts,\n\t\t})\n\tend\n\n\tfor i = 1, 9 do\n\t\tlocal angle = i / 9 * math.pi * 2 + rand(-0.3, 0.3)\n\t\tlocal dir = Vector3.new(math.cos(angle), 0, math.sin(angle))\n\t\tlocal lift = Vector3.new(0, 0.4, 0)\n\t\tskillFx.bolt(pos + dir * rand(14, 20) + lift, pos + dir * rand(40, 60) + lift, {\n\t\t\tcolor = blue,\n\t\t\tthickness = 0.45,\n\t\t\tsegments = 10,\n\t\t\tjag = 4,\n\t\t\tlife = rand(0.2, 0.35),\n\t\t\tflickers = 3,\n\t\t\tbranches = 1,\n\t\t\tflat = true,\n\t\t\tparent = bolts,\n\t\t})\n\tend\n\n\tskillFx.lightFlash(pos + normal * 8, lightBlue, 14, 60, 0.7, true)\n\tskillFx.lightFlash(cloudBase, blue, 10, 60, 0.5, true)\n\n\tskillFx.dustRing(pos, {\n\t\tcolor = groundColor:Lerp(Color3.fromRGB(200, 205, 215), 0.45),\n\t\temitters = 22,\n\t\tperEmitter = 3,\n\t\tspeed = NumberRange.new(70, 115),\n\t\tsize = NumberSequence.new(6, 18),\n\t\tlifetime = NumberRange.new(1, 1.7),\n\t\tradius = 6,\n\t\theight = 1.5,\n\t\tdrag = 3.2,\n\t})\n\tskillFx.sparks(pos + normal, blue, 80)\n\tskillFx.chunks(pos, {\n\t\tcount = 16,\n\t\tmaterial = hit.Material,\n\t\tcolor = groundColor,\n\t\tsize = NumberRange.new(1.2, 3.2),\n\t\tspeed = NumberRange.new(25, 60),\n\t\tup = NumberRange.new(45, 85),\n\t\tlife = 2.4,\n\t})\n\n\tskillFx.groundDecal(pos + normal * 0.05, normal, {\n\t\ttexture = crackTexture,\n\t\tsize = 44,\n\t\tlifetime = 1.2,\n\t\tglow = true,\n\t\tcolor = ColorSequence.new(lightBlue, blue),\n\t\ttransparency = NumberSequence.new({\n\t\t\tNumberSequenceKeypoint.new(0, 0),\n\t\t\tNumberSequenceKeypoint.new(0.5, 0.25),\n\t\t\tNumberSequenceKeypoint.new(1, 1),\n\t\t}),\n\t})\n\tskillFx.groundDecal(pos, normal, {\n\t\ttexture = crackTexture,\n\t\tsize = 44,\n\t\tlifetime = 3,\n\t\tcolor = ColorSequence.new(Color3.fromRGB(22, 22, 28)),\n\t\ttransparency = NumberSequence.new({\n\t\t\tNumberSequenceKeypoint.new(0, 0.1),\n\t\t\tNumberSequenceKeypoint.new(0.75, 0.1),\n\t\t\tNumberSequenceKeypoint.new(1, 1),\n\t\t}),\n\t})\n\ttask.delay(0.5, skillFx.smolder, pos, normal, 12, 1.3, blue)\n\n\tlocal camDist = (workspace.CurrentCamera.CFrame.Position - pos).Magnitude\n\tlocal k = math.clamp(1 - camDist / 260, 0.3, 1)\n\tskillFx.shake(1.5 * k, 0.6, 2.2 * k)\n\tskillFx.fovPunch(10 * k, 0.04, 0.55)\n\n\tlocal victims = skillFx.humanoidsInRadius(pos, 30, caster)\n\tlocal inked = {bolts}\n\tfor _, model in ipairs(skillFx.charactersNear(pos, 140)) do\n\t\ttable.insert(inked, model)\n\tend\n\n\tlocal cc = skillFx.impactFrames({\n\t\t{saturation = -1, brightness = 1, time = 0.04},\n\t\t{saturation = -1, brightness = -1, time = 0.04},\n\t\t{saturation = -1, contrast = 2.5, time = 0.04},\n\t\t{saturation = -1, brightness = 0.3, contrast = 0.5, time = 0.04},\n\t})\n\tskillFx.mirrorImpactFrames(cc, {\n\t\tfocus = pos,\n\t\tmodels = inked,\n\t\tlines = 46,\n\t\tonDone = function()\n\t\t\tfor _, model in ipairs(victims) do\n\t\t\t\tif model.Parent then\n\t\t\t\t\tskillFx.hitFlash(model, blue, 0.45)\n\t\t\t\tend\n\t\t\tend\n\t\t\tskillFx.tint({Brightness = 0.12, Contrast = 0.1, TintColor = Color3.fromRGB(215, 235, 255)}, 0.02, 0.05, 0.45)\n\t\tend,\n\t})\nend\n\nreturn elThorFx","shared/Modules/Knockback.lua":"local players = game:GetService(\"Players\")\nlocal replicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal runService = game:GetService(\"RunService\")\n\nlocal characters = require(script.Parent:WaitForChild(\"Characters\"))\n\nlocal knockback = {}\n\nif runService:IsServer() then\n\tknockback.remote = Instance.new(\"RemoteEvent\")\n\tknockback.remote.Name = \"KnockbackRemote\"\n\tknockback.remote.Parent = replicatedStorage\nelse\n\tknockback.remote = replicatedStorage:WaitForChild(\"KnockbackRemote\")\nend\n\nfunction knockback.apply(model, root, direction, distance, height, time)\n\tlocal hum = model:FindFirstChildOfClass(\"Humanoid\")\n\tif hum and hum.PlatformStand then\n\t\tpcall(function()\n\t\t\thum:ChangeState(Enum.HumanoidStateType.Physics)\n\t\tend)\n\tend\n\n\tlocal flat = Vector3.new(direction.X, 0, direction.Z)\n\tif flat.Magnitude < 0.001 then\n\t\tflat = Vector3.zero\n\t\tdistance = 0\n\telse\n\t\tflat = flat.Unit\n\tend\n\n\tlocal params = characters.excludeParams()\n\n\tlocal wall = distance > 0 and workspace:Raycast(root.Position, flat * distance, params)\n\tif wall then\n\t\tdistance = math.max(0, (wall.Position - root.Position).Magnitude - 1.5)\n\tend\n\n\tlocal rise = 0\n\tlocal here = workspace:Raycast(root.Position, Vector3.new(0, -12, 0), params)\n\tlocal there = workspace:Raycast(root.Position + flat * distance + Vector3.new(0, 6, 0), Vector3.new(0, -30, 0), params)\n\tif here and there then\n\t\trise = there.Position.Y - here.Position.Y\n\tend\n\n\tlocal old = root:FindFirstChild(\"KnockbackVelocity\")\n\tif old then old:Destroy() end\n\told = root:FindFirstChild(\"KnockbackAtt\")\n\tif old then old:Destroy() end\n\n\tlocal att = Instance.new(\"Attachment\")\n\tatt.Name = \"KnockbackAtt\"\n\tatt.Parent = root\n\n\tlocal lv = Instance.new(\"LinearVelocity\")\n\tlv.Name = \"KnockbackVelocity\"\n\tlv.Attachment0 = att\n\tlv.RelativeTo = Enum.ActuatorRelativeTo.World\n\tlv.MaxForce = math.huge\n\tlv.Parent = root\n\n\tlocal start = os.clock()\n\tlocal conn\n\tlocal function update()\n\t\tlocal t = (os.clock() - start) / time\n\t\tif t >= 1 or not lv.Parent or not root.Parent then\n\t\t\tconn:Disconnect()\n\t\t\tlv:Destroy()\n\t\t\tatt:Destroy()\n\t\t\treturn\n\t\tend\n\t\tlocal horizontal = flat * (2 * distance * (1 - t) / time)\n\t\tlocal vertical = (4 * height * (1 - 2 * t) + rise) / time\n\t\tlv.VectorVelocity = horizontal + Vector3.new(0, vertical, 0)\n\tend\n\tconn = runService.Stepped:Connect(update)\n\tupdate()\nend\n\nlocal lent = {}\n\nlocal function lend(model, owner, time)\n\tlocal entry = lent[model]\n\tif not entry then\n\t\tentry = {parts = {}}\n\t\tfor _, part in ipairs(model:GetDescendants()) do\n\t\t\tif part:IsA(\"BasePart\") then\n\t\t\t\tlocal ok, auto = pcall(part.GetNetworkOwnershipAuto, part)\n\t\t\t\tif ok then\n\t\t\t\t\tentry.parts[part] = {auto = auto, owner = part:GetNetworkOwner()}\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tlent[model] = entry\n\tend\n\n\tfor part in pairs(entry.parts) do\n\t\tpcall(part.SetNetworkOwner, part, owner)\n\tend\n\n\tlocal token = {}\n\tentry.token = token\n\ttask.delay(time + 0.25, function()\n\t\tif entry.token ~= token then return end\n\t\tlent[model] = nil\n\t\tfor part, prev in pairs(entry.parts) do\n\t\t\tif part:IsDescendantOf(workspace) then\n\t\t\t\tif prev.auto then\n\t\t\t\t\tpcall(part.SetNetworkOwnershipAuto, part)\n\t\t\t\telse\n\t\t\t\t\tpcall(part.SetNetworkOwner, part, prev.owner)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\nend\n\nfunction knockback.send(model, root, direction, distance, height, time, caster)\n\tlocal victim = players:GetPlayerFromCharacter(model)\n\tlocal owner = victim or caster\n\n\tif not victim then\n\t\tlend(model, owner, time)\n\tend\n\n\tif owner then\n\t\tknockback.remote:FireClient(owner, model, root, direction, distance, height, time)\n\telse\n\t\tknockback.apply(model, root, direction, distance, height, time)\n\tend\nend\n\nreturn knockback","shared/Modules/PlungeFX.lua":"local debris = game:GetService(\"Debris\")\nlocal tweenService = game:GetService(\"TweenService\")\n\nlocal skillFx = require(script.Parent:WaitForChild(\"SkillFX\"))\n\nlocal red = Color3.fromRGB(255, 40, 40)\nlocal dustColor = Color3.fromRGB(205, 205, 210)\n\nlocal plungeFx = {}\n\nlocal leap\n\nlocal function endLeap(fovRelease)\n\tif not leap then return end\n\tleap.stopGhosts()\n\tleap.releaseFov(fovRelease)\n\tleap = nil\nend\n\nfunction plungeFx.leap(character)\n\tendLeap()\n\n\tlocal hl = Instance.new(\"Highlight\")\n\thl.FillColor = Color3.fromRGB(255, 0, 0)\n\thl.OutlineColor = Color3.fromRGB(255, 0, 0)\n\thl.FillTransparency = 0.6\n\thl.OutlineTransparency = 0\n\thl.DepthMode = Enum.HighlightDepthMode.Occluded\n\thl.Parent = character\n\ttweenService:Create(hl, TweenInfo.new(0.8, Enum.EasingStyle.Sine), {FillTransparency = 1, OutlineTransparency = 1}):Play()\n\tdebris:AddItem(hl, 0.9)\n\n\tlocal params = RaycastParams.new()\n\tparams.FilterDescendantsInstances = {character}\n\tlocal ground = workspace:Raycast(character.HumanoidRootPart.Position, Vector3.new(0, -12, 0), params)\n\tif ground then\n\t\tskillFx.dustRing(ground.Position, {\n\t\t\tcolor = skillFx.surfaceColor(ground):Lerp(dustColor, 0.6),\n\t\t\temitters = 10,\n\t\t\tperEmitter = 2,\n\t\t\tspeed = NumberRange.new(18, 30),\n\t\t\tsize = NumberSequence.new(2, 5),\n\t\t\tlifetime = NumberRange.new(0.5, 0.8),\n\t\t\tradius = 1,\n\t\t\theight = 0.6,\n\t\t\tdrag = 4,\n\t\t})\n\tend\n\n\tlocal current = {\n\t\tstopGhosts = skillFx.afterimages(character, {\n\t\t\tcolor = Color3.fromRGB(255, 55, 55),\n\t\t\tinterval = 0.035,\n\t\t\tfade = 0.3,\n\t\t\ttransparency = 0.55,\n\t\t\tmaxTime = 1.2,\n\t\t}),\n\t\treleaseFov = skillFx.fovHold(7, 0.18),\n\t}\n\tleap = current\n\n\ttask.delay(2.5, function()\n\t\tif leap == current then\n\t\t\tendLeap()\n\t\tend\n\tend)\nend\n\nfunction plungeFx.slam(character, direction)\n\tendLeap(0.3)\n\tskillFx.fovPunch(-6, 0.03, 0.35)\n\tskillFx.shake(0.25, 0.25)\n\n\tlocal cc = skillFx.impactFrames({\n\t\t{saturation = -1, contrast = 2.2, time = 0.04},\n\t\t{saturation = -0.4, contrast = 0.5, brightness = 0.08, tint = Color3.fromRGB(255, 170, 170), time = 0.04},\n\t})\n\tlocal focus = character.HumanoidRootPart.Position + direction * 6\n\tskillFx.mirrorImpactFrames(cc, {\n\t\tfocus = focus,\n\t\tmodels = skillFx.charactersNear(focus, 40),\n\t\taccent = red,\n\t\tlines = 30,\n\t})\n\n\ttask.delay(0.08, skillFx.tint, {Saturation = -0.2, Contrast = 0.1, TintColor = Color3.fromRGB(255, 225, 225)}, 0.02, 0.06, 0.3)\nend\n\nfunction plungeFx.hit(model)\n\tskillFx.hitFlash(model, red, 0.35)\nend\n\nfunction plungeFx.slamWorld(center)\n\tskillFx.dustRing(center, {\n\t\tcolor = dustColor,\n\t\temitters = 14,\n\t\tperEmitter = 2,\n\t\tspeed = NumberRange.new(35, 55),\n\t\tsize = NumberSequence.new(2.5, 7),\n\t\tlifetime = NumberRange.new(0.7, 1.1),\n\t\tradius = 2,\n\t\theight = 0.8,\n\t\tdrag = 3.5,\n\t})\n\tskillFx.lightFlash(center + Vector3.new(0, 4, 0), Color3.fromRGB(255, 120, 110), 6, 24, 0.35)\n\n\tlocal sinkRocks = skillFx.rockRing(center, 5, 3, 1.5, 0.7)\n\ttask.delay(1, sinkRocks, 0.4)\nend\n\nreturn plungeFx","shared/Modules/SkillFX.lua":"local debris = game:GetService(\"Debris\")\nlocal lighting = game:GetService(\"Lighting\")\nlocal players = game:GetService(\"Players\")\nlocal runService = game:GetService(\"RunService\")\nlocal tweenService = game:GetService(\"TweenService\")\n\nlocal characters = require(script.Parent:WaitForChild(\"Characters\"))\n\nlocal smokeTexture = \"rbxasset://textures/particles/smoke_main.dds\"\nlocal sparkleTexture = \"rbxasset://textures/particles/sparkles_main.dds\"\nlocal white = Color3.new(1, 1, 1)\nlocal black = Color3.new(0, 0, 0)\n\nlocal skillFx = {}\n\nlocal function rand(min, max)\n\treturn min + math.random() * (max - min)\nend\n\nlocal function fxFolder()\n\tlocal name = runService:IsClient() and \"ClientFX\" or \"ServerFX\"\n\tlocal folder = workspace:FindFirstChild(name)\n\tif not folder then\n\t\tfolder = Instance.new(\"Folder\")\n\t\tfolder.Name = name\n\t\tfolder.Parent = workspace\n\tend\n\treturn folder\nend\nskillFx.folder = fxFolder\n\nlocal function newPart()\n\tlocal p = Instance.new(\"Part\")\n\tp.Anchored = true\n\tp.CanCollide = false\n\tp.CanQuery = false\n\tp.CanTouch = false\n\tp.CastShadow = false\n\tp.TopSurface = Enum.SurfaceType.Smooth\n\tp.BottomSurface = Enum.SurfaceType.Smooth\n\treturn p\nend\n\nlocal function holderAt(cf, size)\n\tlocal p = newPart()\n\tp.Transparency = 1\n\tp.Size = size or Vector3.one * 0.2\n\tp.CFrame = cf\n\tp.Parent = fxFolder()\n\treturn p\nend\n\nlocal function surfaceCFrame(pos, normal)\n\tlocal up = normal.Unit\n\tlocal side = (math.abs(up.Z) < 0.9 and Vector3.zAxis or Vector3.xAxis):Cross(up).Unit\n\treturn CFrame.fromMatrix(pos, side, up)\nend\n\nfunction skillFx.surfaceColor(result)\n\tif result.Instance:IsA(\"Terrain\") then\n\t\treturn result.Instance:GetMaterialColor(result.Material)\n\tend\n\treturn result.Instance.Color\nend\n\nfunction skillFx.charactersNear(pos, radius)\n\tlocal found = {}\n\tfor _, model in ipairs(characters.all()) do\n\t\tif (model:GetPivot().Position - pos).Magnitude <= radius then\n\t\t\ttable.insert(found, model)\n\t\tend\n\tend\n\treturn found\nend\n\nfunction skillFx.humanoidsInRadius(pos, radius, ignore)\n\tlocal seen, list = {}, {}\n\tfor _, part in ipairs(workspace:GetPartBoundsInRadius(pos, radius)) do\n\t\tlocal model = part:FindFirstAncestorOfClass(\"Model\")\n\t\tif model and model ~= ignore and not seen[model] and model:FindFirstChildOfClass(\"Humanoid\") then\n\t\t\tseen[model] = true\n\t\t\ttable.insert(list, model)\n\t\tend\n\tend\n\treturn list\nend\n\nfunction skillFx.lightFlash(pos, color, brightness, range, duration, flicker)\n\tlocal holder = holderAt(CFrame.new(pos))\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Color = color\n\tlight.Range = math.min(range, 60)\n\tlight.Brightness = brightness\n\tlight.Shadows = false\n\tlight.Parent = holder\n\n\ttask.spawn(function()\n\t\tif flicker then\n\t\t\tfor _ = 1, 4 do\n\t\t\t\tlight.Brightness = brightness * rand(0.15, 1.1)\n\t\t\t\ttask.wait(0.03)\n\t\t\tend\n\t\t\tlight.Brightness = brightness\n\t\tend\n\t\ttweenService:Create(light, TweenInfo.new(duration, Enum.EasingStyle.Quad), {Brightness = 0}):Play()\n\tend)\n\tdebris:AddItem(holder, duration + 0.5)\nend\n\nfunction skillFx.glow(part, color, brightness, range)\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Color = color\n\tlight.Range = range\n\tlight.Brightness = 0\n\tlight.Shadows = false\n\tlight.Parent = part\n\n\tlocal on = true\n\ttask.spawn(function()\n\t\twhile on and light.Parent do\n\t\t\tlight.Brightness = brightness * rand(0.5, 1.15)\n\t\t\ttask.wait(rand(0.02, 0.05))\n\t\tend\n\tend)\n\n\treturn function()\n\t\tif not on then return end\n\t\ton = false\n\t\ttweenService:Create(light, TweenInfo.new(0.15), {Brightness = 0}):Play()\n\t\tdebris:AddItem(light, 0.25)\n\tend\nend\n\nlocal function boltPoints(a, b, segments, jag, flat)\n\tlocal dir = b - a\n\tlocal unit = dir.Unit\n\tlocal side = unit:Cross(math.abs(unit.Y) > 0.9 and Vector3.xAxis or Vector3.yAxis).Unit\n\tlocal other = unit:Cross(side).Unit\n\n\tlocal points = {a}\n\tfor i = 1, segments - 1 do\n\t\tlocal t = i / segments\n\t\tlocal amp = jag * math.sin(t * math.pi)\n\t\tlocal offset = side * rand(-1, 1) * amp + other * rand(-1, 1) * amp * (flat and 0.15 or 1)\n\t\ttable.insert(points, a + dir * t + offset)\n\tend\n\ttable.insert(points, b)\n\treturn points\nend\n\nlocal function drawBolt(points, thickness, color, parent)\n\tlocal n = #points - 1\n\tfor i = 1, n do\n\t\tlocal p0, p1 = points[i], points[i + 1]\n\t\tlocal len = (p1 - p0).Magnitude\n\t\tif len > 0.001 then\n\t\t\tlocal w = thickness * (1 - 0.6 * (i - 1) / n)\n\t\t\tlocal seg = newPart()\n\t\t\tseg.Material = Enum.Material.Neon\n\t\t\tseg.Color = color\n\t\t\tseg.Size = Vector3.new(w, w, len + w)\n\t\t\tseg.CFrame = CFrame.lookAt((p0 + p1) / 2, p1)\n\t\t\tseg.Parent = parent\n\t\tend\n\tend\nend\n\nfunction skillFx.bolt(a, b, o)\n\tlocal model = Instance.new(\"Model\")\n\tmodel.Name = \"Bolt\"\n\n\tlocal function build()\n\t\tmodel:ClearAllChildren()\n\t\tlocal points = boltPoints(a, b, o.segments, o.jag, o.flat)\n\t\tdrawBolt(points, o.thickness, o.color, model)\n\n\t\tlocal dir = (b - a).Unit\n\t\tlocal length = (b - a).Magnitude\n\t\tfor _ = 1, o.branches do\n\t\t\tlocal from = points[math.random(2, #points - 1)]\n\t\t\tlocal spread = Vector3.new(rand(-1, 1), o.flat and 0 or rand(-0.6, 0.3), rand(-1, 1))\n\t\t\tlocal to = from + (dir + spread * 0.9).Unit * length * rand(0.15, 0.35)\n\t\t\tlocal branch = boltPoints(from, to, math.max(3, math.floor(o.segments / 2)), o.jag * 0.5, o.flat)\n\t\t\tdrawBolt(branch, o.thickness * 0.5, o.color, model)\n\t\tend\n\tend\n\n\tbuild()\n\tmodel.Parent = o.parent or fxFolder()\n\n\ttask.spawn(function()\n\t\tlocal slice = o.life / (o.flickers + 1)\n\t\tfor _ = 1, o.flickers do\n\t\t\ttask.wait(slice * 0.7)\n\t\t\tmodel:ClearAllChildren()\n\t\t\ttask.wait(slice * 0.3)\n\t\t\tif not model.Parent then return end\n\t\t\tbuild()\n\t\tend\n\t\ttask.wait(slice)\n\t\tmodel:Destroy()\n\tend)\nend\n\nfunction skillFx.dustRing(center, o)\n\tlocal emitter = Instance.new(\"ParticleEmitter\")\n\temitter.Texture = smokeTexture\n\temitter.Color = ColorSequence.new(o.color)\n\temitter.LightEmission = 0\n\temitter.LightInfluence = 1\n\temitter.Size = o.size\n\temitter.Transparency = NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 0.35),\n\t\tNumberSequenceKeypoint.new(0.6, 0.65),\n\t\tNumberSequenceKeypoint.new(1, 1),\n\t})\n\temitter.Lifetime = o.lifetime\n\temitter.Speed = o.speed\n\temitter.Drag = o.drag\n\temitter.SpreadAngle = Vector2.new(6, 6)\n\temitter.Rotation = NumberRange.new(0, 360)\n\temitter.RotSpeed = NumberRange.new(-40, 40)\n\temitter.Acceleration = Vector3.new(0, 3, 0)\n\temitter.EmissionDirection = Enum.NormalId.Front\n\temitter.Enabled = false\n\n\tlocal holder = holderAt(CFrame.new(center))\n\tfor i = 1, o.emitters do\n\t\tlocal angle = i / o.emitters * math.pi * 2 + rand(-0.1, 0.1)\n\t\tlocal dir = Vector3.new(math.cos(angle), 0, math.sin(angle))\n\t\tlocal pos = dir * o.radius + Vector3.new(0, o.height, 0)\n\n\t\tlocal att = Instance.new(\"Attachment\")\n\t\tatt.CFrame = CFrame.lookAt(pos, pos + dir)\n\t\tatt.Parent = holder\n\n\t\tlocal e = emitter:Clone()\n\t\te.Parent = att\n\t\te:Emit(o.perEmitter)\n\tend\n\temitter:Destroy()\n\tdebris:AddItem(holder, o.lifetime.Max + 0.5)\nend\n\nfunction skillFx.sparks(pos, color, count)\n\tlocal holder = holderAt(CFrame.new(pos))\n\tlocal att = Instance.new(\"Attachment\")\n\tatt.Parent = holder\n\n\tlocal e = Instance.new(\"ParticleEmitter\")\n\te.Texture = sparkleTexture\n\te.Color = ColorSequence.new(white, color)\n\te.LightEmission = 1\n\te.LightInfluence = 0\n\te.Size = NumberSequence.new(0.9, 0)\n\te.Lifetime = NumberRange.new(0.4, 0.9)\n\te.Speed = NumberRange.new(35, 85)\n\te.SpreadAngle = Vector2.new(70, 70)\n\te.Acceleration = Vector3.new(0, -110, 0)\n\te.Drag = 1.5\n\te.EmissionDirection = Enum.NormalId.Top\n\te.Enabled = false\n\te.Parent = att\n\te:Emit(count)\n\n\tdebris:AddItem(holder, 1.5)\nend\n\nfunction skillFx.chunks(center, o)\n\tlocal params = characters.excludeParams()\n\tlocal chunks = {}\n\n\tfor _ = 1, o.count do\n\t\tlocal s = rand(o.size.Min, o.size.Max)\n\t\tlocal part = newPart()\n\t\tpart.CastShadow = true\n\t\tpart.Size = Vector3.new(s, s * rand(0.5, 0.9), s * rand(0.7, 1.2))\n\t\tpart.Material = o.material\n\t\tpart.Color = o.color\n\n\t\tlocal angle = rand(0, math.pi * 2)\n\t\tlocal dir = Vector3.new(math.cos(angle), 0, math.sin(angle))\n\t\tpart.CFrame = CFrame.new(center + dir * rand(1, 4) + Vector3.new(0, s, 0))\n\t\t\t* CFrame.Angles(rand(0, 6.28), rand(0, 6.28), rand(0, 6.28))\n\t\tpart.Parent = fxFolder()\n\n\t\ttable.insert(chunks, {\n\t\t\tpart = part,\n\t\t\tvel = dir * rand(o.speed.Min, o.speed.Max) + Vector3.new(0, rand(o.up.Min, o.up.Max), 0),\n\t\t\tspin = Vector3.new(rand(-9, 9), rand(-9, 9), rand(-9, 9)),\n\t\t\tbounces = 0,\n\t\t\thalf = part.Size.Y / 2,\n\t\t})\n\tend\n\n\tlocal conn\n\tconn = runService.Heartbeat:Connect(function(dt)\n\t\tlocal moving = false\n\t\tfor _, c in ipairs(chunks) do\n\t\t\tif not c.done and c.part.Parent then\n\t\t\t\tmoving = true\n\t\t\t\tc.vel = c.vel - Vector3.new(0, 140 * dt, 0)\n\t\t\t\tlocal move = c.vel * dt\n\t\t\t\tlocal hit = c.vel.Y < 0 and workspace:Raycast(c.part.Position, move - Vector3.new(0, c.half, 0), params)\n\t\t\t\tif hit then\n\t\t\t\t\tc.bounces = c.bounces + 1\n\t\t\t\t\tc.part.CFrame = CFrame.new(hit.Position + Vector3.new(0, c.half, 0)) * c.part.CFrame.Rotation\n\t\t\t\t\tif c.bounces >= 3 or math.abs(c.vel.Y) < 20 then\n\t\t\t\t\t\tc.done = true\n\t\t\t\t\telse\n\t\t\t\t\t\tc.vel = Vector3.new(c.vel.X * 0.55, -c.vel.Y * 0.35, c.vel.Z * 0.55)\n\t\t\t\t\t\tc.spin = c.spin * 0.5\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\tlocal w = c.spin * dt\n\t\t\t\t\tc.part.CFrame = (c.part.CFrame + move) * CFrame.Angles(w.X, w.Y, w.Z)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tif not moving then\n\t\t\tconn:Disconnect()\n\t\tend\n\tend)\n\n\ttask.delay(o.life - 0.35, function()\n\t\tfor _, c in ipairs(chunks) do\n\t\t\tif c.part.Parent then\n\t\t\t\ttweenService:Create(c.part, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {\n\t\t\t\t\tSize = c.part.Size * 0.1,\n\t\t\t\t\tTransparency = 1,\n\t\t\t\t}):Play()\n\t\t\tend\n\t\tend\n\tend)\n\ttask.delay(o.life, function()\n\t\tconn:Disconnect()\n\t\tfor _, c in ipairs(chunks) do\n\t\t\tc.part:Destroy()\n\t\tend\n\tend)\nend\n\nfunction skillFx.rockRing(center, radius, length, width, height, probe)\n\tlocal params = characters.excludeParams()\n\tlocal count = math.ceil(2 * math.pi * radius / length)\n\tlocal rocks = {}\n\n\tfor i = 1, count do\n\t\tlocal angle = i / count * math.pi * 2 + rand(-0.025, 0.025)\n\t\tlocal dist = radius + rand(-0.25, 0.25)\n\t\tlocal x, z = center.X + math.cos(angle) * dist, center.Z + math.sin(angle) * dist\n\t\tlocal ground = workspace:Raycast(Vector3.new(x, center.Y + (probe or 20), z), Vector3.new(0, -400, 0), params)\n\t\tif ground then\n\t\t\tlocal l = length * rand(0.7, 1.3)\n\t\t\tlocal h = height * rand(0.7, 1.3)\n\n\t\t\tlocal rock = newPart()\n\t\t\trock.CastShadow = true\n\t\t\trock.Size = Vector3.new(width * rand(0.7, 1.3), h, l)\n\t\t\trock.Material = ground.Material\n\t\t\trock.Color = skillFx.surfaceColor(ground)\n\n\t\t\tlocal pos = Vector3.new(x, ground.Position.Y, z)\n\t\t\tlocal rest = CFrame.lookAt(pos, pos + Vector3.new(-math.sin(angle), 0, math.cos(angle)))\n\t\t\t\t* CFrame.Angles(rand(-0.3, 0.3), rand(-0.2, 0.2), rand(-0.3, 0.3))\n\t\t\tlocal buried = rest - Vector3.new(0, l / 2 + h, 0)\n\n\t\t\trock.CFrame = buried\n\t\t\trock.Parent = fxFolder()\n\t\t\ttweenService:Create(rock, TweenInfo.new(0.18, Enum.EasingStyle.Back), {CFrame = rest + Vector3.new(0, h * 0.3, 0)}):Play()\n\t\t\ttable.insert(rocks, {rock, buried})\n\t\tend\n\tend\n\n\treturn function(time)\n\t\tfor _, data in ipairs(rocks) do\n\t\t\ttweenService:Create(data[1], TweenInfo.new(time, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {CFrame = data[2]}):Play()\n\t\t\tdebris:AddItem(data[1], time)\n\t\tend\n\tend\nend\n\nfunction skillFx.groundDecal(pos, normal, o)\n\tlocal holder = holderAt(surfaceCFrame(pos + normal * 0.15, normal))\n\n\tlocal e = Instance.new(\"ParticleEmitter\")\n\te.Texture = o.texture\n\te.Orientation = Enum.ParticleOrientation.VelocityPerpendicular\n\te.EmissionDirection = Enum.NormalId.Top\n\te.Speed = NumberRange.new(0.001)\n\te.SpreadAngle = Vector2.zero\n\te.Size = NumberSequence.new(o.size)\n\te.Lifetime = NumberRange.new(o.lifetime)\n\te.Rotation = NumberRange.new(0, 360)\n\te.Color = o.color\n\te.Transparency = o.transparency\n\te.LightEmission = o.glow and 1 or 0\n\te.LightInfluence = o.glow and 0 or 1\n\te.Enabled = false\n\te.Parent = holder\n\te:Emit(1)\n\n\tdebris:AddItem(holder, o.lifetime + 0.3)\nend\n\nfunction skillFx.smolder(pos, normal, radius, duration, emberColor)\n\tlocal holder = holderAt(surfaceCFrame(pos + normal * 0.5, normal), Vector3.new(radius * 2, 0.2, radius * 2))\n\n\tlocal smoke = Instance.new(\"ParticleEmitter\")\n\tsmoke.Texture = smokeTexture\n\tsmoke.EmissionDirection = Enum.NormalId.Top\n\tsmoke.Shape = Enum.ParticleEmitterShape.Box\n\tsmoke.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\tsmoke.Rate = 28\n\tsmoke.Speed = NumberRange.new(3, 8)\n\tsmoke.SpreadAngle = Vector2.new(15, 15)\n\tsmoke.Drag = 0.6\n\tsmoke.Acceleration = Vector3.new(0, 2, 0)\n\tsmoke.Lifetime = NumberRange.new(1.6, 2.4)\n\tsmoke.Size = NumberSequence.new(5, 13)\n\tsmoke.Rotation = NumberRange.new(0, 360)\n\tsmoke.RotSpeed = NumberRange.new(-25, 25)\n\tsmoke.Color = ColorSequence.new(Color3.fromRGB(70, 72, 80), Color3.fromRGB(35, 35, 40))\n\tsmoke.Transparency = NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 1),\n\t\tNumberSequenceKeypoint.new(0.15, 0.55),\n\t\tNumberSequenceKeypoint.new(1, 1),\n\t})\n\tsmoke.LightInfluence = 1\n\tsmoke.Parent = holder\n\n\tlocal embers = Instance.new(\"ParticleEmitter\")\n\tembers.Texture = sparkleTexture\n\tembers.EmissionDirection = Enum.NormalId.Top\n\tembers.Shape = Enum.ParticleEmitterShape.Box\n\tembers.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\tembers.Rate = 30\n\tembers.Speed = NumberRange.new(4, 12)\n\tembers.SpreadAngle = Vector2.new(25, 25)\n\tembers.Acceleration = Vector3.new(0, 5, 0)\n\tembers.Lifetime = NumberRange.new(0.5, 1)\n\tembers.Size = NumberSequence.new(0.45, 0)\n\tembers.Color = ColorSequence.new(white, emberColor)\n\tembers.LightEmission = 1\n\tembers.LightInfluence = 0\n\tembers.Parent = holder\n\n\ttask.delay(duration, function()\n\t\tsmoke.Enabled = false\n\t\tembers.Enabled = false\n\tend)\n\tdebris:AddItem(holder, duration + 2.6)\nend\n\nfunction skillFx.hitFlash(model, outline, duration)\n\tlocal hl = Instance.new(\"Highlight\")\n\thl.FillColor = white\n\thl.OutlineColor = outline\n\thl.FillTransparency = 0\n\thl.OutlineTransparency = 0\n\thl.DepthMode = Enum.HighlightDepthMode.Occluded\n\thl.Parent = model\n\n\ttask.delay(0.06, function()\n\t\tif hl.Parent then\n\t\t\ttweenService:Create(hl, TweenInfo.new(duration, Enum.EasingStyle.Quad), {FillTransparency = 1, OutlineTransparency = 1}):Play()\n\t\tend\n\tend)\n\tdebris:AddItem(hl, duration + 0.2)\nend\n\nlocal shakes = {}\nlocal kicks = {}\nlocal baseFov\nlocal bound = false\n\nlocal function kickValue(k, now)\n\tif k.releaseAt and now >= k.releaseAt then\n\t\tlocal r = (now - k.releaseAt) / k.release\n\t\tif r >= 1 then\n\t\t\treturn 0, true\n\t\tend\n\t\treturn k.peak * (1 - r) ^ 2, false\n\tend\n\tlocal t = math.clamp((now - k.start) / k.attack, 0, 1)\n\treturn k.amount * (1 - (1 - t) ^ 2), false\nend\n\nlocal function updateCamera()\n\tlocal cam = workspace.CurrentCamera\n\tlocal now = os.clock()\n\n\tlocal offset, roll = Vector3.zero, 0\n\tfor i = #shakes, 1, -1 do\n\t\tlocal s = shakes[i]\n\t\tlocal t = (now - s.start) / s.duration\n\t\tif t >= 1 then\n\t\t\ttable.remove(shakes, i)\n\t\telse\n\t\t\tlocal f = (1 - t) ^ 2\n\t\t\toffset = offset + Vector3.new(rand(-1, 1), rand(-1, 1), rand(-0.5, 0.5)) * s.magnitude * f\n\t\t\troll = roll + rand(-1, 1) * s.roll * f\n\t\tend\n\tend\n\n\tlocal fov = 0\n\tfor i = #kicks, 1, -1 do\n\t\tlocal v, done = kickValue(kicks[i], now)\n\t\tif done then\n\t\t\ttable.remove(kicks, i)\n\t\telse\n\t\t\tfov = fov + v\n\t\tend\n\tend\n\n\tcam.CFrame = cam.CFrame * CFrame.new(offset) * CFrame.Angles(0, 0, math.rad(roll))\n\tif baseFov then\n\t\tcam.FieldOfView = baseFov + fov\n\tend\n\n\tif #shakes == 0 and #kicks == 0 then\n\t\trunService:UnbindFromRenderStep(\"SkillFXCamera\")\n\t\tbound = false\n\t\tbaseFov = nil\n\tend\nend\n\nlocal function bindCamera()\n\tif bound then return end\n\tbound = true\n\trunService:BindToRenderStep(\"SkillFXCamera\", Enum.RenderPriority.Camera.Value + 1, updateCamera)\nend\n\nfunction skillFx.shake(magnitude, duration, roll)\n\ttable.insert(shakes, {start = os.clock(), duration = duration, magnitude = magnitude, roll = roll or 0})\n\tbindCamera()\nend\n\nlocal function addKick(k)\n\tif not baseFov then\n\t\tbaseFov = workspace.CurrentCamera.FieldOfView\n\tend\n\ttable.insert(kicks, k)\n\tbindCamera()\nend\n\nfunction skillFx.fovPunch(amount, attack, release)\n\tlocal now = os.clock()\n\taddKick({start = now, amount = amount, peak = amount, attack = attack, release = release, releaseAt = now + attack})\nend\n\nfunction skillFx.fovHold(amount, attack)\n\tlocal k = {start = os.clock(), amount = amount, attack = attack}\n\taddKick(k)\n\n\tlocal released = false\n\treturn function(release)\n\t\tif released then return end\n\t\treleased = true\n\t\tlocal now = os.clock()\n\t\tk.peak = kickValue(k, now)\n\t\tk.release = release or 0.25\n\t\tk.releaseAt = now\n\tend\nend\n\nfunction skillFx.tint(props, fadeIn, hold, fadeOut)\n\tlocal cc = Instance.new(\"ColorCorrectionEffect\")\n\tcc.Parent = lighting\n\ttweenService:Create(cc, TweenInfo.new(fadeIn, Enum.EasingStyle.Quad), props):Play()\n\n\ttask.delay(fadeIn + hold, function()\n\t\tlocal tween = tweenService:Create(cc, TweenInfo.new(fadeOut, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {\n\t\t\tBrightness = 0,\n\t\t\tContrast = 0,\n\t\t\tSaturation = 0,\n\t\t\tTintColor = white,\n\t\t})\n\t\ttween:Play()\n\t\ttween.Completed:Wait()\n\t\tcc:Destroy()\n\tend)\nend\n\nfunction skillFx.impactFrames(frames)\n\tlocal cc = Instance.new(\"ColorCorrectionEffect\")\n\n\tlocal function apply(f)\n\t\tcc.Brightness = f.brightness or 0\n\t\tcc.Contrast = f.contrast or 0\n\t\tcc.Saturation = f.saturation or 0\n\t\tcc.TintColor = f.tint or white\n\tend\n\n\tapply(frames[1])\n\tcc.Parent = lighting\n\ttask.spawn(function()\n\t\tfor i, f in ipairs(frames) do\n\t\t\tif i > 1 then apply(f) end\n\t\t\ttask.wait(f.time)\n\t\tend\n\t\tcc:Destroy()\n\tend)\n\treturn cc\nend\n\nlocal function inkFor(cc)\n\tif cc.Brightness >= 0.9 then\n\t\treturn black, black\n\telseif cc.Brightness <= -0.9 then\n\t\treturn white, white\n\telseif cc.Contrast >= 2 then\n\t\treturn black, white\n\tend\nend\n\nlocal function focusLines(gui, cam, focus, color, count)\n\tlocal size = cam.ViewportSize\n\tlocal center = size / 2\n\tif focus then\n\t\tlocal p = cam:WorldToViewportPoint(focus)\n\t\tif p.Z > 0 then\n\t\t\tcenter = Vector2.new(math.clamp(p.X, 0, size.X), math.clamp(p.Y, 0, size.Y))\n\t\tend\n\tend\n\n\tlocal reach = size.Magnitude\n\tlocal gap = math.min(size.X, size.Y) * 0.22\n\tfor i = 1, count do\n\t\tlocal angle = (i + math.random() * 0.8) / count * math.pi * 2\n\t\tlocal dir = Vector2.new(math.cos(angle), math.sin(angle))\n\t\tlocal mid = center + dir * (gap * rand(0.75, 1.9) + reach / 2)\n\n\t\tlocal line = Instance.new(\"Frame\")\n\t\tline.AnchorPoint = Vector2.new(0.5, 0.5)\n\t\tline.Position = UDim2.fromOffset(mid.X, mid.Y)\n\t\tline.Size = UDim2.fromOffset(reach, rand(2, 9))\n\t\tline.Rotation = math.deg(angle)\n\t\tline.BackgroundColor3 = color\n\t\tline.BorderSizePixel = 0\n\n\t\tlocal grad = Instance.new(\"UIGradient\")\n\t\tgrad.Transparency = NumberSequence.new({\n\t\t\tNumberSequenceKeypoint.new(0, 1),\n\t\t\tNumberSequenceKeypoint.new(0.12, 0),\n\t\t\tNumberSequenceKeypoint.new(1, 0),\n\t\t})\n\t\tgrad.Parent = line\n\t\tline.Parent = gui\n\tend\nend\n\nfunction skillFx.mirrorImpactFrames(cc, o)\n\tlocal cam = workspace.CurrentCamera\n\n\tlocal gui = Instance.new(\"ScreenGui\")\n\tgui.Name = \"ImpactLines\"\n\tgui.IgnoreGuiInset = true\n\tgui.ResetOnSpawn = false\n\tgui.DisplayOrder = 50\n\tgui.Parent = players.LocalPlayer.PlayerGui\n\n\tlocal highlights = {}\n\tfor i, model in ipairs(o.models) do\n\t\tif i > 24 then break end\n\t\tlocal hl = Instance.new(\"Highlight\")\n\t\thl.Enabled = false\n\t\thl.FillTransparency = 0\n\t\thl.OutlineTransparency = 0\n\t\thl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop\n\t\thl.Parent = model\n\t\ttable.insert(highlights, hl)\n\tend\n\n\tlocal last\n\tlocal conn\n\tconn = runService.RenderStepped:Connect(function()\n\t\tif not cc.Parent then\n\t\t\tconn:Disconnect()\n\t\t\tfor _, hl in ipairs(highlights) do\n\t\t\t\thl:Destroy()\n\t\t\tend\n\t\t\tgui:Destroy()\n\t\t\tif o.onDone then\n\t\t\t\to.onDone()\n\t\t\tend\n\t\t\treturn\n\t\tend\n\n\t\tlocal frame = cc.Brightness .. \"|\" .. cc.Contrast\n\t\tif frame == last then return end\n\t\tlast = frame\n\n\t\tlocal fill, ink = inkFor(cc)\n\t\tfor _, hl in ipairs(highlights) do\n\t\t\thl.Enabled = fill ~= nil\n\t\t\tif fill then\n\t\t\t\thl.FillColor = fill\n\t\t\t\thl.OutlineColor = o.accent or ink\n\t\t\tend\n\t\tend\n\n\t\tgui:ClearAllChildren()\n\t\tif ink and o.lines then\n\t\t\tfocusLines(gui, cam, o.focus, ink, o.lines)\n\t\tend\n\tend)\nend\n\nlocal function ghostPart(source)\n\tlocal archivable = source.Archivable\n\tsource.Archivable = true\n\tlocal copy = source:Clone()\n\tsource.Archivable = archivable\n\n\tfor _, child in ipairs(copy:GetChildren()) do\n\t\tif child:IsA(\"SpecialMesh\") then\n\t\t\tchild.TextureId = \"\"\n\t\telseif not child:IsA(\"DataModelMesh\") then\n\t\t\tchild:Destroy()\n\t\tend\n\tend\n\tif copy:IsA(\"MeshPart\") then\n\t\tpcall(function()\n\t\t\tcopy.TextureID = \"\"\n\t\tend)\n\tend\n\n\tcopy.Anchored = true\n\tcopy.CanCollide = false\n\tcopy.CanQuery = false\n\tcopy.CanTouch = false\n\tcopy.CastShadow = false\n\tcopy.Massless = true\n\tcopy.Reflectance = 0\n\tcopy.Material = Enum.Material.Neon\n\treturn copy\nend\n\nfunction skillFx.afterimages(character, o)\n\tlocal running = true\n\n\ttask.spawn(function()\n\t\tlocal start = os.clock()\n\t\twhile running and character.Parent and os.clock() - start < o.maxTime do\n\t\t\tlocal ghost = Instance.new(\"Model\")\n\t\t\tghost.Name = \"Afterimage\"\n\n\t\t\tlocal parts = {}\n\t\t\tfor _, part in ipairs(character:GetDescendants()) do\n\t\t\t\tif part:IsA(\"BasePart\") and part.Name ~= \"HumanoidRootPart\" and part.Transparency < 0.95 then\n\t\t\t\t\tlocal copy = ghostPart(part)\n\t\t\t\t\tcopy.Color = o.color\n\t\t\t\t\tcopy.Transparency = o.transparency\n\t\t\t\t\tcopy.CFrame = part.CFrame\n\t\t\t\t\tcopy.Parent = ghost\n\t\t\t\t\ttable.insert(parts, copy)\n\t\t\t\tend\n\t\t\tend\n\t\t\tghost.Parent = fxFolder()\n\n\t\t\tfor _, p in ipairs(parts) do\n\t\t\t\ttweenService:Create(p, TweenInfo.new(o.fade, Enum.EasingStyle.Quad), {Transparency = 1}):Play()\n\t\t\tend\n\t\t\tdebris:AddItem(ghost, o.fade + 0.1)\n\t\t\ttask.wait(o.interval)\n\t\tend\n\tend)\n\n\treturn function()\n\t\trunning = false\n\tend\nend\n\nreturn skillFx"};
